		groundHeight = (((Rva0045A000 *)((char *)this + 0x2448))->*thunk.member)(viewPos->x, ((BfmeW3DViewCameraFields *)this)->m_pos.y);
	}
	Real oldGroundLevel = groundState->m_groundLevel;
